package cn.zhuatech.privacy;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.Pattern;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepPrivacyTests{@Autowired MockMvc mvc;
 @Test void sensitiveActivityRequiresApprovedImpactAssessment()throws Exception{long activity=activity("UT-ROPA-01",true,true);mvc.perform(post("/api/privacy-ops/activities/{id}/submit",activity).with(httpBasic("operator","operator123"))).andExpect(status().isConflict());long pia=idOf(mvc.perform(post("/api/privacy-ops/activities/{id}/assessments",activity).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"riskDescription\":\"跨境和敏感信息风险\",\"mitigations\":\"加密、最小化、访问审计\",\"residualRisk\":\"MEDIUM\",\"reviewer\":\"隐私官\"}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/admin/privacy-ops/assessments/{id}/approve",pia).with(httpBasic("admin","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("APPROVED"));mvc.perform(post("/api/privacy-ops/activities/{id}/submit",activity).with(httpBasic("operator","operator123"))).andExpect(status().isOk());mvc.perform(post("/api/admin/privacy-ops/activities/{id}/approve",activity).with(httpBasic("admin","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("APPROVED"));mvc.perform(post("/api/admin/privacy-ops/retention/run").param("organizationCode","UT-PRIV").param("asOf","2030-01-01").with(httpBasic("admin","admin123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.deletionTasksCreated").value(org.hamcrest.Matchers.greaterThanOrEqualTo(1)));}
 @Test void highResidualRiskAssessmentCannotBeApproved()throws Exception{long activity=activity("UT-ROPA-02",true,false);long pia=idOf(mvc.perform(post("/api/privacy-ops/activities/{id}/assessments",activity).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"riskDescription\":\"高风险画像\",\"mitigations\":\"措施不足\",\"residualRisk\":\"HIGH\",\"reviewer\":\"隐私官\"}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/admin/privacy-ops/assessments/{id}/approve",pia).with(httpBasic("admin","admin123"))).andExpect(status().isConflict());}
 @Test void consentRevocationAndVerifiedDeletionRequestWork()throws Exception{long consent=idOf(mvc.perform(post("/api/privacy-ops/consents").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"organizationCode\":\"UT-PRIV\",\"subjectRef\":\"USER-001\",\"purposeCode\":\"MARKETING\",\"noticeVersion\":\"v2\",\"source\":\"WEB\",\"proofReference\":\"PROOF-001\"}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/privacy-ops/consents/{id}/revoke",consent).with(httpBasic("operator","operator123"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("REVOKED"));long request=idOf(mvc.perform(post("/api/privacy-ops/requests").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"organizationCode\":\"UT-PRIV\",\"requestNo\":\"DSR-UT-01\",\"subjectRef\":\"USER-001\",\"requestType\":\"DELETE\",\"channel\":\"WEB\"}")).andExpect(status().isOk()).andReturn());mvc.perform(post("/api/privacy-ops/requests/{id}/fulfill",request).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"responseEvidence\":\"DELETE-EVIDENCE\"}")).andExpect(status().isConflict());mvc.perform(post("/api/privacy-ops/requests/{id}/verify",request).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"assignee\":\"隐私专员\"}")).andExpect(status().isOk());mvc.perform(post("/api/privacy-ops/requests/{id}/fulfill",request).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"responseEvidence\":\"DELETE-EVIDENCE\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.status").value("FULFILLED"));}
 private long activity(String no,boolean sensitive,boolean cross)throws Exception{return idOf(mvc.perform(post("/api/privacy-ops/activities").with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content("{\"organizationCode\":\"UT-PRIV\",\"activityNo\":\""+no+"\",\"name\":\"客户画像\",\"department\":\"市场部\",\"owner\":\"数据负责人\",\"lawfulBasis\":\"同意\",\"dataCategories\":\"联系方式、行为数据\",\"purpose\":\"个性化服务\",\"sensitiveData\":"+sensitive+",\"crossBorder\":"+cross+",\"retentionDays\":365}")).andExpect(status().isOk()).andReturn());}private long idOf(MvcResult r)throws Exception{var m=Pattern.compile("\"id\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
